package com.gamehub.application.controller;
import com.gamehub.application.OperationsService; import java.util.List; import java.time.Instant;
public final class TournamentController { private final OperationsService ops; public TournamentController(OperationsService ops){this.ops=ops;} public List<String> tournaments()throws Exception{return ops.tournaments();} public long create(long organizer,String name,String format,String entrantType,int capacity,long fee)throws Exception{return ops.createTournament(organizer,name,format,entrantType,capacity,fee);} public void configure(long organizer,long tournament,String game,Instant open,Instant close,Instant schedule,String eligibility)throws Exception{ops.configureTournament(organizer,tournament,game,open,close,schedule,eligibility);} public void transition(long organizer,long tournament,String status)throws Exception{ops.changeTournamentStatus(organizer,tournament,status);} }